def semi_cost(sub):
    L=len(sub)
    if L<2: return 10**9
    best=10**9
    for d in range(1,L):
        if L%d: continue
        c=0
        for r in range(d):
            seq=sub[r::d]
            c+=sum(seq[a]!=seq[-1-a] for a in range(len(seq)//2))
        best=min(best,c)
    return best

def brute2879(s,k):
    n=len(s); best=10**9
    for cuts in itertools.combinations(range(1,n),k-1):
        pts=(0,)+cuts+(n,)
        parts=[s[pts[i]:pts[i+1]] for i in range(k)]
        if any(len(p)<2 for p in parts): continue
        best=min(best,sum(semi_cost(p) for p in parts))
    return best

