def brute3223(w,k):
    n=len(w); ans=0
    for i in range(n):
        for j in range(i+1,n+1):
            sub=w[i:j]
            if any(abs(ord(sub[t])-ord(sub[t-1]))>2 for t in range(1,len(sub))): continue
            cc={}
            for ch in sub: cc[ch]=cc.get(ch,0)+1
            if all(v==k for v in cc.values()): ans+=1
    return ans
