def brute3091(nums,l,r):
    cnts={}
    for x in nums: cnts[x]=cnts.get(x,0)+1
    items=list(cnts.items())
    def rec(i,s):
        if i==len(items): return 1 if l<=s<=r else 0
        x,c=items[i]; total=0
        for t in range(c+1):
            ns=s+t*x
            if ns>r: break
            total+=rec(i+1,ns)
        return total
    return rec(0,0)%(10**9+7)
